<script lang="ts">
 import CardFace from '$lib/cards/CardFace.svelte';
 import OriginalCardArt from '$lib/cards/OriginalCardArt.svelte';
 import CardSymbol from '$lib/cards/CardSymbol.svelte';
 import {colonySources,colonizationPreview,type ColonySource} from './colonization-preview';
 import {colonyBenefitBlocker} from './colonization';
 import type {PublicSetup} from './setup';
 import type {TurnMove} from './turn';
 let {game,compact=false,allowed,busy,send,inspect}:{game:PublicSetup;compact?:boolean;allowed:boolean;busy:boolean;send:(move:TurnMove)=>void;inspect:(id:string)=>void}=$props();
 let viewportWidth=$state(0);
 const actor=$derived(game.players.find(p=>p.position===game.activePosition)!);
 let source=$state<ColonySource>('terraforming'),chosen=$state(''),selected=$state<string[]>([]),shipIndex=$state(0),pane=$state<'world'|'settlers'|'outcome'>('settlers'),outcome=$state('returns');
 const slot=$derived(game.systems.find(s=>s.slot===chosen)?.slot??game.systems.find(s=>game.discovery?.outposts[s.slot]?.owner===actor.position)?.slot??game.systems[0]?.slot??'');
 const view=$derived(colonizationPreview(game,actor.position,slot,selected,source));
 const here=$derived(actor.ships.filter(s=>s.location===slot));
 const reason=$derived(view.reason|| (view.card?colonyBenefitBlocker(view.card.id):'No public System remains.')||(!game.discovery?.powerReady?'Preparing the public board…':''));
 const owner=$derived(game.discovery?.outposts[slot]?.owner);
 const ownerName=$derived(game.players.find(p=>p.position===owner)?.name??'No faction');
 const sources=Object.keys(colonySources) as ColonySource[];
 function sourceAvailable(id:ColonySource){return id==='terraforming-guild'?!!game.discovery?.guilds.includes(id):actor.research.includes(id);}
 $effect(()=>{if(!sourceAvailable(source)){const available=sources.find(sourceAvailable);if(available){source=available;selected=[];shipIndex=0;}}});
 function changeSystem(value:string){chosen=value;selected=[];shipIndex=0;}
 function toggleShip(id:string,checked:boolean){selected=checked?[...new Set([...selected,id])]:selected.filter(value=>value!==id);}
</script>
<svelte:window bind:innerWidth={viewportWidth}/>
{#snippet selectors()}<div class="instruments"><label>Printed colonization Action<select aria-label="Colonization Action" bind:value={source} onchange={()=>{selected=[];shipIndex=0;}}>{#each sources as id}<option value={id} disabled={!sourceAvailable(id)}>{colonySources[id].title}{sourceAvailable(id)?'':' · unavailable'}</option>{/each}</select></label><label>Public System<select aria-label="System to colonize" value={slot} onchange={e=>changeSystem(e.currentTarget.value)}>{#each game.systems as system}<option value={system.slot}>{colonizationPreview(game,actor.position,system.slot,[],source).card?.title}</option>{/each}</select></label></div>{/snippet}
{#snippet hero()}{#if view.card}<div class="phone-world"><span class="world-art" aria-hidden="true"><OriginalCardArt id={view.card.id}/></span><div><h3>{view.card.title}</h3><p>{ownerName} · outpost</p><span class="specialties">{#each view.tracks as track}<span><CardSymbol kind={track}/>{track==='food'?'Food':'Ore'}</span>{/each}</span><button onclick={()=>inspect(view.card!.id)}>Full System card ↗</button></div></div>{/if}{/snippet}
{#snippet shipChoice(ship:typeof here[number],i:number)}<label class="ship-object"><input type="checkbox" value={ship.id} checked={selected.includes(ship.id)} onchange={event=>toggleShip(ship.id,event.currentTarget.checked)} aria-label={`Settle Ship ${i+1} · level ${ship.level}`} disabled={busy||!allowed}/><span class="level-cube" aria-hidden="true">{ship.level}</span><strong>Ship {i+1}<small>Level {ship.level} · {ship.level} power</small></strong><span class="selection" aria-hidden="true">{selected.includes(ship.id)?'✓':'○'}</span></label>{/snippet}
{#snippet consequences()}<div class="consequences"><h4>After commitment</h4><p><b>{view.settlers.length-view.populationReturn}</b> settling cubes → Supply{view.populationReturn?' · 1 settler → Population':''}. Fill from the right; full tracks overflow into A.</p><p><b>{view.exiled.length}</b> remaining {view.exiled.length===1?'ship':'ships'} → Deep Space, including opponents.</p><p>Keep the outpost with the colony. Reveal the replacement, then add a matching production disc.</p><p class="bonus"><strong>Colony benefit</strong>{view.bonus}</p></div>{/snippet}
<section class="colony-plan" class:compact aria-label="Colony settlement plan" aria-busy={busy||!game.discovery?.powerReady}>
 {#if compact}<nav class="settlement-tabs" aria-label="Settlement views">{#each ['world','settlers','outcome']as tab}<button aria-pressed={pane===tab} onclick={()=>pane=tab as typeof pane}>{tab==='world'?'System':tab==='settlers'?'Settlers':'Outcome'}</button>{/each}</nav>{:else}{@render selectors()}{/if}
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (The named settlement reader scrolls with the keyboard.) -->
 <div class="settlement-reader" role="region" aria-label="System and settlement consequences" tabindex="0">
 {#if compact}
  {#if pane==='world'}<div class="compact-world">{@render selectors()}{@render hero()}</div>
  {:else if pane==='settlers'}<div class="settler-pager"><button aria-label="Previous settling ship" disabled={here.length<2} onclick={()=>shipIndex=(shipIndex+here.length-1)%here.length}>‹</button><span>{view.card?.title??'Choose a System'}<small>{selected.length} selected · Ship {here.length?Math.min(shipIndex+1,here.length):0} / {here.length}</small></span><button aria-label="Next settling ship" disabled={here.length<2} onclick={()=>shipIndex=(shipIndex+1)%here.length}>›</button></div>{#if here.length}{@const i=Math.min(shipIndex,here.length-1)}{@render shipChoice(here[i],i)}{:else}<p>No owned ships at this System. Choose a public System from the System view.</p>{/if}
  {:else}<label class="outcome-selector">Settlement order<select aria-label="Settlement consequence" bind:value={outcome}><option value="returns">1 · Settlers and exile</option><option value="replacement">2 · Colony and replacement</option><option value="disc">3 · Extra production disc</option><option value="benefit">4 · Printed colony benefit</option></select></label><div class="compact-outcome">{#if outcome==='returns'}<p>{view.settlers.length-view.populationReturn} settling cubes return to rightmost Supply spaces; overflow into A.{view.populationReturn?' One settler returns as Population.':''} {view.exiled.length} remaining ships, including rivals, go to Deep Space.</p>{:else if outcome==='replacement'}<p>Keep the outpost. Reveal a matching-deck replacement; use the other deck if needed. Both empty: leave the slot empty. An attached System is removed without refill.</p>{:else if outcome==='disc'}<p>Keep the original outpost disc. Add a matching production disc or permanent placeholder after replacement. Automation does not increase.</p>{:else}<p>{view.bonus}</p>{/if}</div>{/if}
 {:else if view.card}<div class="composition"><button class="world-face" aria-label={`Inspect selected ${view.card.title} System`} onclick={()=>inspect(view.card!.id)}><CardFace card={view.card} compact={viewportWidth<2200||compact}/><span class="world-cue">Full System card ↗</span></button>{@render hero()}<div class="settlement-details"><div class="power-object" aria-live="polite"><span>Required power <b>{view.requirement}</b></span><span>Selected power <b>{view.selectedPower}</b></span><small>{view.overpayment?`Overpay ${view.overpayment} · no change returned`:view.selectedPower>=view.requirement?'Selected settlers meet the requirement.':'Select enough owned ships at this System'}</small></div><fieldset><legend>Settling ships · {selected.length} selected</legend>{#each here as ship,i}{@render shipChoice(ship,i)}{:else}<p>No owned ships at this System.</p>{/each}</fieldset>{@render consequences()}</div></div>{:else}<p>No colonizable public System remains.</p>{/if}
 </div>
 {#if !compact}<p class="scroll-cue">Scroll the framed settlement reader for ships and complete consequences ↕</p>{/if}
 <div class="commit-colony"><div><strong>{view.card?.title??'Choose a System'} · {view.selectedPower}/{view.requirement} power</strong><p>{view.terms.ore} Ore{view.terms.population?` · return ${view.terms.population} Population to Supply`:''}</p><p class="consequence-summary">{view.settlers.length-view.populationReturn} settlers → Supply{view.populationReturn?' · 1 → Population':''} · {view.exiled.length} {compact?'→ Deep Space':`remaining ${view.exiled.length===1?'ship':'ships'} → Deep Space`}</p><small id="colony-reason">{reason||(compact?view.overpayment?`Overpay ${view.overpayment} · no change`:'Ready to settle':'Replacement stays concealed until commitment. Production choice follows its reveal.')}</small></div><button class="primary" aria-describedby="colony-reason" disabled={busy||!allowed||!!reason} onclick={()=>send({kind:'colonize',source,slot,ships:actor.ships.filter(s=>selected.includes(s.id)).map(({id,level,location})=>({id,level,location}))})}>Colonize {view.card?.title??'System'}</button></div>
</section>
<style>
