t:44px;padding:0;border:0;position:absolute;left:0;top:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer}.level-cube{display:grid;place-items:center;flex:none;width:32px;height:32px;border:1px solid #a1e0ce;border-radius:4px;background:linear-gradient(135deg,#78cbb8,#215c61);box-shadow:inset 3px 3px #b6efcd55,2px 3px #081d22;font:600 23px 'Cormorant Garamond',serif}.ship-object strong{flex:1;font-size:14px}.ship-object small{display:block;font-size:11px;font-weight:400;margin-top:3px}.selection{font-size:23px;color:#93e4d5}.ship-object:focus-within{outline:3px solid #79e5d8;outline-offset:3px}.consequences{padding:12px;border:1px solid #aa925d;border-radius:7px;background:#102c34}.consequences h4{font:600 21px 'Cormorant Garamond',serif;margin:0 0 5px}.consequences p{font-size:13px;line-height:1.35;margin:7px 0}.bonus{border-top:1px solid #b69d6266;padding-top:8px}.bonus strong{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px}.scroll-cue{flex:none;margin:0;font-size:10px;color:#ddcfaa}.commit-colony{flex:none;display:flex;align-items:center;gap:14px;padding:10px 12px;border:1px solid #bca46c;border-radius:8px;background:linear-gradient(120deg,#27443f,#112c35);box-shadow:inset 0 1px #ffffff11}.commit-colony>div{flex:1;min-width:0}.commit-colony strong{font:600 22px 'Cormorant Garamond',serif}.commit-colony p{font-size:13px;margin:4px 0}.commit-colony .consequence-summary{font-size:12px;color:#deebd2}.commit-colony small{font-size:11px;line-height:1.3;display:block}.primary{max-width:44%;background:#185b5d}button{min-height:44px;border:1px solid #baa16a;border-radius:6px;padding:9px 12px;color:#f2e5bf;background:linear-gradient(#36544d,#14323b);font:13px 'Atkinson Hyperlegible',sans-serif;cursor:pointer}button:disabled{opacity:.6;cursor:default}button:focus-visible,select:focus-visible,.settlement-reader:focus-visible{outline:3px solid #7ce8d8;outline-offset:3px}.phone-world{display:none}
@container(max-width:620px){.instruments{gap:6px}.instruments label{font-size:10px}select{font-size:11px;padding:6px}.composition{display:block}.world-face{display:none}.phone-world{display:grid;grid-template-columns:80px minmax(0,1fr);gap:12px;margin-bottom:12px;padding:8px;background:linear-gradient(125deg,#efe0bb,#c5ae80);border:1px solid #ad9258;border-radius:8px;color:#263b35;box-shadow:0 4px #715735}.world-art{display:block;height:80px;border:1px solid #ab915c;background:#152e35;overflow:hidden}.world-art :global(svg){width:100%;height:100%;display:block}.phone-world h3{font:600 25px/1.05 'Cormorant Garamond',serif;margin:0 0 5px}.phone-world p{font-size:11px;margin:4px 0}.phone-world button{min-height:44px;font-size:11px;margin-top:4px}.specialties{display:flex;gap:8px}.specialties>span{display:flex;align-items:center;gap:4px;font-size:11px}.commit-colony{padding:8px;gap:8px;flex-wrap:wrap}.commit-colony strong{font-size:20px}.commit-colony p{font-size:12px}.commit-colony small{font-size:10px}.commit-colony .primary{max-width:none;width:100%}.power-object{padding:8px}.power-object>span{font-size:12px}.consequences{padding:9px}.consequences p{font-size:12px}.settlement-reader{padding:5px}}
.compact .instruments label{font-size:9px}.compact select{font-size:10px;padding:5px}.compact .composition{gap:12px;grid-template-columns:120px minmax(0,1fr)}.compact .power-object{padding:6px}.compact .power-object b{font-size:22px}.compact .power-object>span{font-size:10px}.compact .power-object small{font-size:9px}.compact .ship-object{min-height:44px;padding:5px 8px;gap:8px}.compact .ship-object strong{font-size:12px}.compact .ship-object small{font-size:10px}.compact .level-cube{width:25px;height:25px;font-size:19px}.compact .consequences p{font-size:11px}.compact .commit-colony{flex-wrap:nowrap;padding:7px}.compact .commit-colony strong{font-size:17px}.compact .commit-colony p,.compact .commit-colony small{font-size:10px}.compact .commit-colony .primary{width:auto;max-width:43%;font-size:11px;padding:6px}

